import React from 'react';

const Contact = () => (
  <section id="contact" className="py-5">
    <div className="container">
      <h2 className="text-center mb-4">Contact</h2>
      <p className="text-center">Email: Ojhasasmita87@gmail.com | Phone: +91 84550 97964</p>
      <p className="text-center">
        <a href="https://www.linkedin.com/in/sasmita-ojha-8ba569285/" target="_blank" rel="noopener noreferrer">LinkedIn</a>
      </p>
    </div>
  </section>
);

export default Contact;
